"""Shared request validation."""
from __future__ import annotations

from typing import Annotated

from fastapi import Path

# Ids are generated by the API (hex, "ref-<hex>", "profile-<content type>"), so a strict pattern is safe and keeps
# anything else (quotes, slashes, wildcards) out of search filters, blob names and log lines.
VIDEO_ID_PATTERN = r"^[A-Za-z0-9_-]{1,128}$"

VideoId = Annotated[str, Path(pattern=VIDEO_ID_PATTERN, description="MomentLens video id")]
